// ─── File: VideoDemo.java ───
// Runnable demo of the async pipeline + adaptive playback.
// Each class would be its own file in a real project.
package com.bank.video;

import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class VideoDemo {
    private static final Logger log = Logger.getLogger(VideoDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) throws Exception {
        ObjectStorage storage = new ObjectStorage();
        BlockingQueue<Video> jobQueue = new LinkedBlockingQueue<>();
        Map<String, Video> catalog = new ConcurrentHashMap<>();
        UploadService uploadService = new UploadService(storage, jobQueue, catalog);

        // Background transcode worker (async processing)
        TranscodeWorker worker = new TranscodeWorker(storage, jobQueue, catalog,
                List.of(240, 480, 720, 1080));
        Thread workerThread = new Thread(worker, "transcode-worker");
        workerThread.start();

        // Rajesh uploads a product explainer video → accepted INSTANTLY, status PROCESSING
        Video v = uploadService.upload("SAV2001", "home_loan_explainer.mp4", 500_000_000L);
        log.info("Upload accepted: " + v.id + " status=" + v.status + " (processing async)");

        Thread.sleep(300);  // let the worker transcode
        worker.stop(); workerThread.join(500);

        Video ready = catalog.get(v.id);
        log.info("After processing: " + ready.id + " status=" + ready.status
                + " renditions=" + ready.renditions.size());

        // Adaptive playback: player picks rendition by measured bandwidth
        AdaptiveBitratePlayer player = new AdaptiveBitratePlayer(ready);
        log.info("Rajesh on office WiFi (8 Mbps):  plays " + player.selectRendition(8000) + "p");
        log.info("Rajesh on train 3G (1.2 Mbps):   plays " + player.selectRendition(1200) + "p");
        log.info("Rajesh tunnel, weak (0.4 Mbps):  plays " + player.selectRendition(400) + "p");

        // Serve segments from CDN edge, not origin
        log.info("Segment URL (CDN edge): " + player.segmentUrl(480, 1));

        // View tracking
        ViewTracker tracker = new ViewTracker();
        tracker.record(ready.id, "SAV2001", "PLAY");
        tracker.record(ready.id, "SAV2001", "QUALITY_SWITCH_720_TO_480");
        tracker.record(ready.id, "SAV2001", "COMPLETE");
    }
}

