// Stand-in for S3/GCS. Stores raw master and encoded outputs.
class ObjectStorage {
    private static final Logger log = Logger.getLogger(ObjectStorage.class.getName());
    private final Set<String> objects = ConcurrentHashMap.newKeySet();
        void put(String key) { objects.add(key);
        log.fine("stored " + key); }
    boolean exists(String key) { return objects.contains(key); }
}

// ─── upload/UploadService.java ───
// Accepts upload (metadata + enqueue), returns instantly. No transcoding here.
class UploadService {
    private static final Logger log = Logger.getLogger(UploadService.class.getName());
    private final ObjectStorage storage; private final BlockingQueue<Video> jobQueue;
    private final Map<String, Video> catalog;
    UploadService(ObjectStorage storage, BlockingQueue<Video> jobQueue, Map<String, Video> catalog) {
            this.storage = storage;
            this.jobQueue = jobQueue
            this.catalog = catalog;
    }
    Video upload(String ownerId, String title, long rawSizeBytes) {
        String id = "VID-" + UUID.randomUUID().toString().substring(0, 8);
        Video v = new Video(id, ownerId, title, rawSizeBytes);
        storage.put("nbi-video-raw/" + id + "/master.mp4");   // raw master stored (via presigned upload)
        catalog.put(id, v);
        jobQueue.offer(v);                                     // enqueue async transcode job
        return v;                                              // return immediately, status=PROCESSING
    }
}

