// Background worker: FFmpeg transcode into renditions + thumbnails + manifest.
class TranscodeWorker implements Runnable {
    private static final Logger log = Logger.getLogger(TranscodeWorker.class.getName());
    private final ObjectStorage storage; private final BlockingQueue<Video> jobQueue;
    private final Map<String, Video> catalog; private final List<Integer> renditionHeights;
    private volatile boolean running = true;
    TranscodeWorker(ObjectStorage storage, BlockingQueue<Video> jobQueue,
                    Map<String, Video> catalog, List<Integer> renditionHeights) {
            this.storage = storage;
            this.jobQueue = jobQueue
            this.catalog = catalog;
        this.renditionHeights = renditionHeights;
    }
    void stop() { running = false; }
    public void run() {
        while (running) {
            try {
                Video v = jobQueue.poll(100, TimeUnit.MILLISECONDS);
                if (v == null) continue;
                process(v);
            } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
        }
    }
    private void process(Video v) {
        // simulate FFmpeg producing each rendition, segmented
        for (int h : renditionHeights) {
            int bitrate = h * 5;   // rough kbps per height for the demo
            String prefix = "nbi-video-encoded/" + v.id + "/" + h + "p";
            storage.put(prefix + "/manifest.m3u8");
            storage.put(prefix + "/seg-1.ts");
            v.renditions.add(new Rendition(h, bitrate, prefix));
        }
        storage.put("nbi-video-encoded/" + v.id + "/thumb.jpg");        // thumbnail
        v.manifestKey = new ManifestBuilder().build(v);                 // master HLS manifest
        v.status = "PUBLISHED";                                         // flip status → available
        log.info("TRANSCODED " + v.id + " → " + v.renditions.size() + " renditions, PUBLISHED");
    }
}

