// ─── playback/AdaptiveBitratePlayer.java ───
// Picks the highest rendition that fits the measured bandwidth.
class AdaptiveBitratePlayer {
    private final Video video;
    AdaptiveBitratePlayer(Video video) { this.video = video; }
    int selectRendition(int bandwidthKbps) {
        int chosen = video.renditions.get(0).height;   // lowest as safe default
        for (Rendition r : video.renditions)
            if (r.bitrateKbps <= bandwidthKbps && r.height >= chosen) chosen = r.height;
        return chosen;
    }
    String segmentUrl(int height, int segment) {
        return "https://cdn.nbi.com/video/" + video.id + "/" + height + "p/seg-" + segment + ".ts";
    }
}

